messages.content:
Tool response:
Tool: create_contact_note
Description: Create Contact Note
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_mrn": {
          "type": "string",
          "description": "Medical Record Number of the patient",
          "title": "Patient Mrn"
        },
        "visit_date": {
          "type": "string",
          "description": "Date of the visit in YYYY-MM-DD format",
          "title": "Visit Date"
        },
        "raw_transcript": {
          "type": "string",
          "description": "Raw transcript text of the contact note",
          "title": "Raw Transcript"
        },
        "assigned_user_code": {
          "type": "string",
          "description": "User code of the social worker to whom the note is assigned",
          "title": "Assigned User Code"
        },
        "document_code": {
          "type": "string",
          "description": "Document code associated with the contact note",
          "title": "Document Code"
        }
      },
      "required": [
        "patient_mrn",
        "visit_date",
        "raw_transcript",
        "assigned_user_code",
        "document_code"
      ]
    }
